// StackRightGeometry.ts
// Owns: tiny helpers that build primitive box visuals (pallet, shelves, cartons, ghost, arrow)
// from one 1 cm box mesh + one unlit material that is cloned per box. These are the obvious
// placeholder visuals; swap the boxMesh / baseMaterial @inputs on the controller to upgrade.
// Scale always lives on the leaf "Visual" child, never on a node that owns a collider.
// Must not: hold game state or create text.

export class BoxFactory {
  constructor(private mesh: RenderMesh, private baseMaterial: Material) {}

  makeMaterial(color: vec4, translucent: boolean): Material {
    const mat = this.baseMaterial.clone()
    mat.mainPass.baseColor = color
    if (translucent) {
      mat.mainPass.blendMode = BlendMode.Normal
      mat.mainPass.depthWrite = false
    }
    return mat
  }

  /** Creates a child SceneObject with a box visual of `size` cm centred at `localPos`. */
  makeBox(parent: SceneObject, name: string, size: vec3, localPos: vec3, color: vec4,
    translucent: boolean = false): RenderMeshVisual {
    const so = global.scene.createSceneObject(name)
    so.setParent(parent)
    const t = so.getTransform()
    t.setLocalPosition(localPos)
    t.setLocalScale(size)
    const rmv = so.createComponent("Component.RenderMeshVisual") as RenderMeshVisual
    rmv.mesh = this.mesh
    rmv.mainMaterial = this.makeMaterial(color, translucent)
    return rmv
  }

  /** 12 thin bars outlining a box of `size` centred at the parent's origin. */
  makeWireBox(parent: SceneObject, name: string, size: vec3, thickness: number, color: vec4): SceneObject {
    const root = global.scene.createSceneObject(name)
    root.setParent(parent)
    const mat = this.makeMaterial(color, true)
    for (let i = 0; i < 12; i++) {
      const bar = global.scene.createSceneObject("Edge" + i)
      bar.setParent(root)
      const rmv = bar.createComponent("Component.RenderMeshVisual") as RenderMeshVisual
      rmv.mesh = this.mesh
      rmv.mainMaterial = mat
    }
    BoxFactory.layoutWireBox(root, size, thickness)
    return root
  }

  static layoutWireBox(root: SceneObject, size: vec3, th: number): void {
    const hx = size.x / 2, hy = size.y / 2, hz = size.z / 2
    const specs: [vec3, vec3][] = []
    for (const sy of [-1, 1]) for (const sz of [-1, 1]) specs.push([new vec3(0, sy * hy, sz * hz), new vec3(size.x + th, th, th)])
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) specs.push([new vec3(sx * hx, 0, sz * hz), new vec3(th, size.y + th, th)])
    for (const sx of [-1, 1]) for (const sy of [-1, 1]) specs.push([new vec3(sx * hx, sy * hy, 0), new vec3(th, th, size.z + th)])
    for (let i = 0; i < 12 && i < root.getChildrenCount(); i++) {
      const t = root.getChild(i).getTransform()
      t.setLocalPosition(specs[i][0])
      t.setLocalScale(specs[i][1])
    }
  }
}
// StackRightController.ts
// Stack Right: pallet-building trainer. Owns ALL game state (next carton, placed count,
// mistakes, timer) and the rules: ghost on grab, snap within 15 cm, wrong carton / wrong spot
// -> slide back + red tip + mistake, released off the pallet -> slide back (no mistake),
// completion card, reset, next-carton glow, off-view arrow + chime.
//
// Expects (@input): the authored Pallet, ShelfBay, PickList root (8 Carton_i_* children in pick
// order), Ghost, OffViewArrow, ResetPost SceneObjects; the four StackRightLabelUI panels
// (GhostTag, Counter, TipText, CompletionCard); the StackRightResetButtonUI; the 1 cm box mesh
// and unlit base material used for every placeholder visual.
//
// Real SIK grab/release events and the LEAF test hooks (simulateGrab / simulateRelease) run
// through the same handleGrab / handleRelease code path.
// Must not: build UI text itself (labels live in the *UI.ts modules).
import {Interactable} from "SpectaclesInteractionKit.lspkg/Components/Interaction/Interactable/Interactable"
import {InteractableManipulation} from "SpectaclesInteractionKit.lspkg/Components/Interaction/InteractableManipulation/InteractableManipulation"
import WorldCameraFinderProvider from "SpectaclesInteractionKit.lspkg/Providers/CameraProvider/WorldCameraFinderProvider"
import {PICK_LIST, CartonSpec, PALLET_SIZE_CM, ghostTagText} from "./StackRightPickList"
import {BoxFactory} from "./StackRightGeometry"
import {StackRightLabelUI} from "./StackRightLabelUI"
import {StackRightResetButtonUI} from "./StackRightResetButtonUI"
import {StackRightCartonLabelUI} from "./StackRightCartonLabelUI"

const SFX_CHIME = requireAsset("../GeneratedSFX/StackRightChime.wav") as AudioTrackAsset
const SFX_SNAP = requireAsset("../GeneratedSFX/StackRightSnap.wav") as AudioTrackAsset
const SFX_MISTAKE = requireAsset("../GeneratedSFX/StackRightMistake.wav") as AudioTrackAsset
const SFX_COMPLETE = requireAsset("../GeneratedSFX/StackRightComplete.wav") as AudioTrackAsset

const CHIME_COOLDOWN_SEC = 6
const OFF_PALLET_MARGIN_CM = 5

export const TIP_WRONG_SPOT = "Wrong spot. Drop it on the ghost."
export const TIP_NOT_YET = "Not this one yet. Follow the arrow."

interface CartonState {
  index: number
  spec: CartonSpec
  so: SceneObject
  home: vec3
  placed: boolean
  grabbed: boolean
  returning: boolean
  returnFrom: vec3
  returnT: number
  hovered: boolean
  interactable: Interactable
  manip: InteractableManipulation
  bodyMat: Material
  glow: SceneObject
  glowMat: Material
}

@component
export class StackRightController extends BaseScriptComponent {
  @ui.label('<span style="color: #60A5FA;">StackRightController – pallet-building trainer rules + test API</span>')
  @ui.separator

  @ui.label('<span style="color: #60A5FA;">References</span>')
  @ui.group_start("References")
  @input
  @hint("Pallet root: on the floor, origin at the centre of its footprint")
  pallet: SceneObject
  @input
  @hint("Shelf bay root: on the floor to the user's right")
  shelfBay: SceneObject
  @input
  @hint("PickList (stand-in for barcode scan): its 8 children are the cartons, in pick order")
  pickList: SceneObject
  @input
  @hint("Ghost carton root (child of Pallet)")
  ghost: SceneObject
  @input
  @hint("Arrow on the pallet edge that points at the next carton when it is out of view")
  offViewArrow: SceneObject
  @input
  @hint("Short post under the Reset button")
  resetPost: SceneObject
  @input
  @hint("Tag on the ghost: 'Layer N · Heavy · 14 kg'")
  ghostTag: StackRightLabelUI
  @input
  @hint("'3 / 8' counter on the pallet's near edge")
  counter: StackRightLabelUI
  @input
  @hint("Red tip shown on the pallet for a few seconds after a mistake")
  tipText: StackRightLabelUI
  @input
  @hint("Completion card: time, mistakes, 'Wrap and label'")
  completionCard: StackRightLabelUI
  @input
  @hint("Reset pallet button")
  resetButton: StackRightResetButtonUI
  @input
  @hint("1 cm box mesh used for every placeholder visual")
  boxMesh: RenderMesh
  @input
  @hint("Unlit material cloned for every placeholder visual")
  baseMaterial: Material
  @ui.group_end

  @ui.separator
  @ui.label('<span style="color: #60A5FA;">Settings</span>')
  @ui.group_start("Settings")
  @input
  @hint("Release within this horizontal distance (cm) of the ghost to snap")
  @widget(new SliderWidget(5, 40, 1))
  snapDistanceCm: number = 15

  @input
  @hint("Mouse-friendly allowance: how far ABOVE the ghost (cm) a release still snaps. Below, the limit is snapDistanceCm.")
  @widget(new SliderWidget(0, 120, 1))
  dropHeightAllowanceCm: number = 60

  @input
  @hint("How long the red tip stays on the pallet (s)")
  @widget(new SliderWidget(1, 10, 0.5))
  tipDurationSec: number = 4

  @input
  @hint("Place the floor this far below the user's eyes at start (cm). The work area root (this object's parent) is moved to camera.y - eyeHeightCm.")
  @widget(new SliderWidget(100, 200, 1))
  eyeHeightCm: number = 150

  @input("vec4", "{0.6,1,1,0.3}")
  @hint("Ghost fill colour (pale cyan, about 30% fill)")
  @widget(new ColorWidget())
  ghostColor: vec4 = new vec4(0.6, 1, 1, 0.3)

  @input("vec4", "{1,1,0.55,0.35}")
  @hint("Soft glow around the next carton on the shelf")
  @widget(new ColorWidget())
  glowColor: vec4 = new vec4(1, 1, 0.55, 0.35)

  @input("vec4", "{1,0.35,0.35,1}")
  @hint("Tip text colour (bright red, not dark)")
  @widget(new ColorWidget())
  tipColor: vec4 = new vec4(1, 0.35, 0.35, 1)
  @ui.group_end

  @ui.separator
  @ui.label('<span style="color: #60A5FA;">Debug</span>')
  @ui.group_start("Debug")
  @input
  @hint("Print grab/release decisions to the log")
  debugLogs: boolean = false
  @ui.group_end

  // ---- state (single owner) ----
  private cartons: CartonState[] = []
  private nextIndex = 0
  private placedCount = 0
  private mistakes = 0
  private complete = false
  private grabbedIndex = -1
  private startTime = -1
  private finishTime = -1
  private tipHideAt = -1
  private ghostTagString = ""
  private tipString = ""
  private completionString = ""
  private arrowVisible = false
  private nextInView = true
  private lastChimeAt = -100
  private wasOutOfView = false

  private factory: BoxFactory
  private ghostFill: SceneObject
  private ghostWire: SceneObject
  private palletT: Transform
  private returnDuration = 0.6
  private audio: {[k: string]: AudioComponent} = {}
  private ready = false

  onAwake(): void {
    if (!this.validateRefs()) return
    this.factory = new BoxFactory(this.boxMesh, this.baseMaterial)
    this.palletT = this.pallet.getTransform()
    this.alignFloorToCamera()
    this.buildPalletVisual()
    this.buildShelfVisual()
    this.buildResetPostVisual()
    this.buildGhost()
    this.buildArrow()
    this.buildCartons()
    this.buildAudio()

    this.createEvent("OnStartEvent").bind(() => this.onStart())
    this.createEvent("UpdateEvent").bind(() => this.onUpdate())
  }

  private onStart(): void {
    for (const c of this.cartons) {
      const i = c.index
      c.manip.onManipulationStart.add(() => this.handleGrab(i))
      c.manip.onManipulationEnd.add(() => this.handleRelease(i, c.so.getTransform().getWorldPosition()))
      c.interactable.onHoverEnter.add(() => this.setHover(i, true))
      c.interactable.onHoverExit.add(() => this.setHover(i, false))
    }
    this.resetButton.onReset.add(() => this.reset())
    this.tipText.setTextColor(this.tipColor)
    this.ready = true
    this.reset()
    const cam = WorldCameraFinderProvider.getInstance()
    print("[StackRight] ready. camera world pos = " + cam.getTransform().getWorldPosition() +
      " pallet = " + this.getPalletWorldPosition() + " shelf = " + this.getShelfWorldPosition())
  }

  // =====================================================================================
  // Public API (used by the scene and by LEAF tests)
  // =====================================================================================
  getPlacedCount(): number { return this.placedCount }
  getMistakes(): number { return this.mistakes }
  /** Index into the pick list of the carton that is due next (8 when complete). */
  getNextIndex(): number { return this.nextIndex }
  isComplete(): boolean { return this.complete }
  isGhostVisible(): boolean { return this.ghost.enabled }
  getGhostTagText(): string { return this.ghostTag.isVisible() ? this.ghostTagString : "" }
  isGhostTagVisible(): boolean { return this.ghostTag.isVisible() }
  getTipText(): string { return this.tipString }
  isTipVisible(): boolean { return this.tipText.isVisible() }
  isCompletionVisible(): boolean { return this.completionCard.isVisible() }
  getCompletionText(): string { return this.completionString }
  getCounterText(): string { return this.counter.getText() }
  isArrowVisible(): boolean { return this.arrowVisible }
  isNextCartonInView(): boolean { return this.nextInView }
  getCartonCount(): number { return this.cartons.length }
  getCartonName(i: number): string { return this.cartons[i] ? this.cartons[i].so.name : "" }
  isCartonPlaced(i: number): boolean { return !!this.cartons[i] && this.cartons[i].placed }
  isCartonReturning(i: number): boolean { return !!this.cartons[i] && this.cartons[i].returning }
  isCartonGlowing(i: number): boolean { return !!this.cartons[i] && this.cartons[i].glow.enabled }
  getGrabbedIndex(): number { return this.grabbedIndex }
  getGhostWorldPosition(): vec3 { return this.ghost.getTransform().getWorldPosition() }
  /** Where carton i snaps to on the pallet (centre of the carton). */
  getSlotWorldPosition(i: number): vec3 { return this.palletT.getWorldTransform().multiplyPoint(this.slotCenterLocal(PICK_LIST[i])) }
  getCartonWorldPosition(i: number): vec3 { return this.cartons[i].so.getTransform().getWorldPosition() }
  getCartonHomePosition(i: number): vec3 { return this.cartons[i].home }
  getPalletWorldPosition(): vec3 { return this.palletT.getWorldPosition() }
  getShelfWorldPosition(): vec3 { return this.shelfBay.getTransform().getWorldPosition() }
  getCameraWorldPosition(): vec3 { return WorldCameraFinderProvider.getInstance().getTransform().getWorldPosition() }

  /** Test hook: same code path as a real SIK grab. */
  simulateGrab(cartonIndex: number): void {
    this.handleGrab(cartonIndex)
  }

  /** Test hook: moves carton to worldPos, then runs the same code path as a real SIK release. */
  simulateRelease(cartonIndex: number, worldPos: vec3): void {
    const c = this.cartons[cartonIndex]
    if (!c) return
    if (!c.placed) c.so.getTransform().setWorldPosition(worldPos)
    this.handleRelease(cartonIndex, worldPos)
  }

  /** Test hook: same path as pinching the Reset button. */
  pressReset(): void {
    this.resetButton.press()
  }

  /** Clears the pallet and returns every carton to the shelf. */
  reset(): void {
    for (const c of this.cartons) {
      c.placed = false
      c.grabbed = false
      c.returning = false
      c.hovered = false
      c.so.getTransform().setWorldPosition(c.home)
      c.so.getTransform().setWorldRotation(quat.quatIdentity())
      c.interactable.enabled = true
      c.manip.enabled = true
      c.bodyMat.mainPass.baseColor = c.spec.color
    }
    this.nextIndex = 0
    this.placedCount = 0
    this.mistakes = 0
    this.complete = false
    this.grabbedIndex = -1
    this.startTime = -1
    this.finishTime = -1
    this.tipHideAt = -1
    this.tipString = ""
    this.completionString = ""
    this.ghostTagString = ""
    this.ghost.enabled = false
    this.ghostTag.setVisible(false)
    this.tipText.setVisible(false)
    this.completionCard.setVisible(false)
    this.wasOutOfView = false
    this.updateCounter()
    this.updateGlow()
    this.log("reset")
  }

  // =====================================================================================
  // Rules
  // =====================================================================================
  private handleGrab(i: number): void {
    const c = this.cartons[i]
    if (!c || c.placed || this.complete) return
    c.grabbed = true
    c.returning = false
    this.grabbedIndex = i
    if (this.startTime < 0) this.startTime = getTime()
    if (i === this.nextIndex) {
      this.showGhostFor(c.spec)
    } else {
      this.hideGhost()
    }
    this.updateGlow()
    this.log("grab " + c.so.name + (i === this.nextIndex ? " (correct, ghost shown)" : " (not next)"))
  }

  private handleRelease(i: number, worldPos: vec3): void {
    const c = this.cartons[i]
    if (!c || c.placed) return
    c.grabbed = false
    if (this.grabbedIndex === i) this.grabbedIndex = -1
    this.hideGhost()

    const local = this.palletT.getInvertedWorldTransform().multiplyPoint(worldPos)
    const half = PALLET_SIZE_CM.x / 2 + OFF_PALLET_MARGIN_CM
    const onPallet = Math.abs(local.x) <= half && Math.abs(local.z) <= half && local.y >= -20 && local.y <= 250

    if (this.complete) {
      this.sendHome(c)
      return
    }

    if (i === this.nextIndex) {
      const slot = this.slotCenterLocal(c.spec)
      const dx = local.x - slot.x
      const dz = local.z - slot.z
      const dy = local.y - slot.y
      const horiz = Math.sqrt(dx * dx + dz * dz)
      if (horiz <= this.snapDistanceCm && dy >= -this.snapDistanceCm && dy <= Math.max(this.snapDistanceCm, this.dropHeightAllowanceCm)) {
        this.place(c)
      } else if (onPallet) {
        this.mistake(c, TIP_WRONG_SPOT)
      } else {
        this.log("released " + c.so.name + " off the pallet: back to shelf, no mistake")
        this.sendHome(c)
      }
    } else {
      if (onPallet) {
        const due = PICK_LIST[this.nextIndex]
        const tip = !c.spec.heavy && due.heavy
          ? c.spec.tipName + " " + c.spec.tipVerb + " on top. Heavy first."
          : TIP_NOT_YET
        this.mistake(c, tip)
      } else {
        this.log("released " + c.so.name + " off the pallet: back to shelf, no mistake")
        this.sendHome(c)
      }
    }
    this.updateGlow()
  }

  private place(c: CartonState): void {
    const t = c.so.getTransform()
    t.setWorldPosition(this.palletT.getWorldTransform().multiplyPoint(this.slotCenterLocal(c.spec)))
    t.setWorldRotation(this.palletT.getWorldRotation())
    c.placed = true
    c.returning = false
    c.manip.enabled = false
    c.interactable.enabled = false
    c.bodyMat.mainPass.baseColor = c.spec.color
    this.placedCount++
    this.nextIndex++
    this.play("snap")
    this.log("placed " + c.so.name + " -> " + this.placedCount + "/" + this.cartons.length)
    if (this.nextIndex >= this.cartons.length) this.finish()
    this.updateCounter()
    this.updateGlow()
  }

  private mistake(c: CartonState, tip: string): void {
    this.mistakes++
    this.tipString = tip
    this.tipText.setText(tip)
    this.tipText.setVisible(true)
    this.tipHideAt = getTime() + this.tipDurationSec
    this.play("mistake")
    this.log("mistake #" + this.mistakes + " (" + c.so.name + "): " + tip)
    this.sendHome(c)
  }

  private finish(): void {
    this.complete = true
    this.finishTime = getTime()
    const secs = Math.max(0, Math.round(this.finishTime - (this.startTime < 0 ? this.finishTime : this.startTime)))
    const mm = Math.floor(secs / 60)
    const ss = secs % 60
    const time = mm + ":" + (ss < 10 ? "0" : "") + ss
    this.completionString = "Pallet done!\nTime " + time + "  ·  Mistakes " + this.mistakes + "\nWrap and label the pallet."
    this.completionCard.setText(this.completionString)
    this.completionCard.setVisible(true)
    this.tipText.setVisible(false)
    this.arrowVisible = false
    this.offViewArrow.enabled = false
    this.play("complete")
  }

  private sendHome(c: CartonState): void {
    c.returning = true
    c.returnT = 0
    c.returnFrom = c.so.getTransform().getWorldPosition()
  }

  private showGhostFor(spec: CartonSpec): void {
    const center = this.slotCenterLocal(spec)
    this.ghost.getTransform().setLocalPosition(center)
    this.ghostFill.getTransform().setLocalScale(spec.size)
    BoxFactory.layoutWireBox(this.ghostWire, spec.size.add(new vec3(0.6, 0.6, 0.6)), 0.8)
    this.ghost.enabled = true
    this.ghostTagString = ghostTagText(spec)
    this.ghostTag.setText(this.ghostTagString)
    this.ghostTag.sceneObject.getTransform().setLocalPosition(
      new vec3(center.x, spec.slot.y + spec.size.y + 7, center.z + spec.size.z / 2 + 3))
    this.ghostTag.setVisible(true)
  }

  private hideGhost(): void {
    this.ghost.enabled = false
    this.ghostTag.setVisible(false)
  }

  private slotCenterLocal(spec: CartonSpec): vec3 {
    return new vec3(spec.slot.x, spec.slot.y + spec.size.y / 2, spec.slot.z)
  }

  private updateCounter(): void {
    this.counter.setText(this.placedCount + " / " + this.cartons.length)
  }

  private updateGlow(): void {
    for (const c of this.cartons) {
      c.glow.enabled = !this.complete && c.index === this.nextIndex && !c.grabbed && !c.placed
    }
  }

  private setHover(i: number, on: boolean): void {
    const c = this.cartons[i]
    if (!c || c.placed) return
    c.hovered = on
    const k = on ? 0.4 : 0
    const col = c.spec.color
    c.bodyMat.mainPass.baseColor = new vec4(col.x + (1 - col.x) * k, col.y + (1 - col.y) * k, col.z + (1 - col.z) * k, 1)
  }

  // =====================================================================================
  // Per-frame: slide-back, tip timeout, glow pulse, off-view arrow + chime
  // =====================================================================================
  private onUpdate(): void {
    if (!this.ready) return
    const now = getTime()
    const dt = getDeltaTime()

    for (const c of this.cartons) {
      if (!c.returning) continue
      c.returnT = Math.min(1, c.returnT + dt / this.returnDuration)
      const e = 1 - Math.pow(1 - c.returnT, 3)
      c.so.getTransform().setWorldPosition(vec3.lerp(c.returnFrom, c.home, e))
      if (c.returnT >= 1) {
        c.returning = false
        c.so.getTransform().setWorldRotation(quat.quatIdentity())
      }
    }

    if (this.tipHideAt > 0 && now >= this.tipHideAt) {
      this.tipHideAt = -1
      this.tipText.setVisible(false)
    }

    const pulse = 0.65 + 0.35 * Math.sin(now * 3)
    for (const c of this.cartons) {
      if (c.glow.enabled) {
        c.glowMat.mainPass.baseColor = new vec4(this.glowColor.x, this.glowColor.y, this.glowColor.z, this.glowColor.w * pulse)
      }
    }

    this.updateOffView(now)
  }

  private updateOffView(now: number): void {
    if (this.complete || this.nextIndex >= this.cartons.length) {
      this.arrowVisible = false
      this.offViewArrow.enabled = false
      return
    }
    const next = this.cartons[this.nextIndex]
    const target = next.so.getTransform().getWorldPosition()
    const cam = WorldCameraFinderProvider.getInstance()
    this.nextInView = cam.inFoV(target)
    const show = !this.nextInView && this.grabbedIndex < 0
    this.arrowVisible = show
    this.offViewArrow.enabled = show
    if (show) {
      const from = this.offViewArrow.getTransform().getWorldPosition()
      const dx = target.x - from.x
      const dz = target.z - from.z
      const yaw = Math.atan2(-dz, dx) // arrow geometry points along local +X
      this.offViewArrow.getTransform().setWorldRotation(quat.angleAxis(yaw, vec3.up()))
      if (!this.wasOutOfView && now - this.lastChimeAt >= CHIME_COOLDOWN_SEC) {
        this.lastChimeAt = now
        this.play("chime")
      }
    }
    this.wasOutOfView = show
  }

  // =====================================================================================
  // Build (placeholder visuals on authored roots)
  // =====================================================================================
  /** Puts the floor (work-area root) eyeHeightCm below the camera's current height. */
  private alignFloorToCamera(): void {
    const root = this.sceneObject.getParent()
    if (!root) return
    const cam = WorldCameraFinderProvider.getInstance()
    if (!cam) return
    const camY = cam.getTransform().getWorldPosition().y
    const t = root.getTransform()
    const p = t.getWorldPosition()
    t.setWorldPosition(new vec3(p.x, camY - this.eyeHeightCm, p.z))
    this.log("floor aligned: camera y = " + camY + ", floor y = " + (camY - this.eyeHeightCm))
  }

  private buildPalletVisual(): void {
    const v = global.scene.createSceneObject("PalletVisual")
    v.setParent(this.pallet)
    const wood = new vec4(1.0, 0.8, 0.5, 1)
    const woodLight = new vec4(1.0, 0.88, 0.65, 1)
    const S = PALLET_SIZE_CM.x
    // three bearers along z (bottom 11 cm)
    for (const x of [-S / 2 + 5, 0, S / 2 - 5]) {
      this.factory.makeBox(v, "Bearer", new vec3(10, 11, S), new vec3(x, 5.5, 0), wood)
    }
    // seven deck boards along x (top 4 cm), square to the edges
    const n = 7
    const bw = 13.5
    const gap = (S - n * bw) / (n - 1)
    for (let k = 0; k < n; k++) {
      const z = -S / 2 + bw / 2 + k * (bw + gap)
      this.factory.makeBox(v, "Deck", new vec3(S, 4, bw), new vec3(0, 13, z), woodLight)
    }
  }

  private buildShelfVisual(): void {
    const v = global.scene.createSceneObject("ShelfVisual")
    v.setParent(this.shelfBay)
    const post = new vec4(0.45, 0.65, 1.0, 1)
    const beam = new vec4(1.0, 0.62, 0.25, 1)
    const board = new vec4(0.85, 0.88, 0.95, 1)
    // 240 W (along z) x 60 D (along x); shelf tops at 40 and 100 cm
    for (const x of [-28, 28]) for (const z of [-118, 118]) {
      this.factory.makeBox(v, "Post", new vec3(4, 150, 4), new vec3(x, 75, z), post)
    }
    for (const top of [40, 100]) {
      this.factory.makeBox(v, "Board", new vec3(60, 3, 240), new vec3(0, top - 1.5, 0), board)
      this.factory.makeBox(v, "Beam", new vec3(3, 6, 240), new vec3(-31.5, top - 3, 0), beam)
    }
  }

  private buildResetPostVisual(): void {
    this.factory.makeBox(this.resetPost, "PostVisual", new vec3(4, 84, 4), new vec3(0, 42, 0), new vec4(0.75, 0.8, 0.9, 1))
  }

  private buildGhost(): void {
    this.ghostFill = this.factory.makeBox(this.ghost, "GhostFill", new vec3(1, 1, 1), vec3.zero(), this.ghostColor, true).getSceneObject()
    this.ghostWire = this.factory.makeWireBox(this.ghost, "GhostOutline", new vec3(10, 10, 10), 0.8,
      new vec4(this.ghostColor.x, this.ghostColor.y, this.ghostColor.z, 0.95))
    this.ghost.enabled = false
  }

  private buildArrow(): void {
    const yellow = new vec4(1, 0.95, 0.3, 1)
    // flat arrow on the pallet edge, pointing along local +X
    this.factory.makeBox(this.offViewArrow, "Shaft", new vec3(16, 1.5, 4), new vec3(-4, 0, 0), yellow)
    const head1 = this.factory.makeBox(this.offViewArrow, "HeadA", new vec3(10, 1.5, 3.5), new vec3(5.5, 0, -2.7), yellow).getSceneObject()
    // each head bar leans in toward the tip (+X), so the pair forms a ">" rather than a fork
    head1.getTransform().setLocalRotation(quat.angleAxis(-0.7, vec3.up()))
    const head2 = this.factory.makeBox(this.offViewArrow, "HeadB", new vec3(10, 1.5, 3.5), new vec3(5.5, 0, 2.7), yellow).getSceneObject()
    head2.getTransform().setLocalRotation(quat.angleAxis(0.7, vec3.up()))
    this.offViewArrow.enabled = false
  }

  private buildCartons(): void {
    const n = Math.min(this.pickList.getChildrenCount(), PICK_LIST.length)
    if (n !== PICK_LIST.length) print("[StackRight] WARNING: PickList has " + this.pickList.getChildrenCount() + " children, expected " + PICK_LIST.length)
    for (let i = 0; i < n; i++) {
      const so = this.pickList.getChild(i)
      const spec = PICK_LIST[i]
      const body = this.factory.makeBox(so, "Body", spec.size, vec3.zero(), spec.color)
      const glowRmv = this.factory.makeBox(so, "Glow", spec.size.add(new vec3(5, 5, 5)), vec3.zero(), this.glowColor, true)
      const labels = so.createComponent(StackRightCartonLabelUI.getTypeName()) as StackRightCartonLabelUI
      labels.setup(spec.name, spec.kg + " kg · " + (spec.heavy ? "HEAVY" : "FRAGILE"), spec.size)

      const col = so.createComponent("Physics.ColliderComponent") as ColliderComponent
      const shape = Shape.createBoxShape()
      shape.size = spec.size
      col.shape = shape
      const interactable = so.createComponent(Interactable.getTypeName()) as Interactable
      const manip = so.createComponent(InteractableManipulation.getTypeName()) as InteractableManipulation
      manip.setCanRotate(false)
      manip.setCanScale(false)

      this.cartons.push({
        index: i, spec, so,
        home: so.getTransform().getWorldPosition(),
        placed: false, grabbed: false, returning: false, returnFrom: vec3.zero(), returnT: 0, hovered: false,
        interactable, manip,
        bodyMat: body.mainMaterial,
        glow: glowRmv.getSceneObject(),
        glowMat: glowRmv.mainMaterial,
      })
    }
  }

  private buildAudio(): void {
    const tracks: {[k: string]: AudioTrackAsset} = {chime: SFX_CHIME, snap: SFX_SNAP, mistake: SFX_MISTAKE, complete: SFX_COMPLETE}
    for (const k of Object.keys(tracks)) {
      const so = global.scene.createSceneObject("Sfx_" + k)
      so.setParent(this.sceneObject)
      const a = so.createComponent("Component.AudioComponent") as AudioComponent
      a.audioTrack = tracks[k]
      a.playbackMode = Audio.PlaybackMode.LowLatency
      a.volume = 0.8
      this.audio[k] = a
    }
  }

  private play(k: string): void {
    const a = this.audio[k]
    if (!a) return
    if (a.isPlaying()) a.stop(false)
    a.play(1)
  }

  private log(msg: string): void {
    if (this.debugLogs) print("[StackRight] " + msg)
  }

  private validateRefs(): boolean {
    const missing: string[] = []
    const refs: {[k: string]: any} = {
      pallet: this.pallet, shelfBay: this.shelfBay, pickList: this.pickList, ghost: this.ghost,
      offViewArrow: this.offViewArrow, resetPost: this.resetPost, ghostTag: this.ghostTag, counter: this.counter,
      tipText: this.tipText, completionCard: this.completionCard, resetButton: this.resetButton,
      boxMesh: this.boxMesh, baseMaterial: this.baseMaterial,
    }
    for (const k of Object.keys(refs)) if (isNull(refs[k])) missing.push(k)
    if (missing.length > 0) {
      print("[StackRight] ERROR: unwired @input(s): " + missing.join(", "))
      return false
    }
    return true
  }
}

// StackRightTestDriver.ts
// TEST/DEMO ONLY. Stand-in for LEAF while LEAF isn't installed: drives the controller through its
// test hooks (simulateGrab / simulateRelease / pressReset, the same code path as real SIK grabs)
// a moment after the Lens starts.
//   mode "off"      - does nothing (normal play)
//   mode "selftest" - checks done criteria 1-5, prints "[StackRightTest] PASS/FAIL ..." lines, then resets
//   mode "ghost"    - 3 cartons placed, next carton held above the pallet: ghost + tag showing
//   mode "mistake"  - chips dropped on the pallet while heavy is due: red tip showing
//   mode "complete" - all 8 placed: completion card showing
// Expects: the StackRightController component. Must not: change game rules.
import {StackRightController} from "./StackRightController"
import {ghostTagText, PICK_LIST} from "./StackRightPickList"

@component
export class StackRightTestDriver extends BaseScriptComponent {
  @ui.label('<span style="color: #60A5FA;">StackRightTestDriver – test/demo states (set mode to off for normal play)</span>')
  @ui.separator
  @input
  @hint("The StackRightController to drive")
  controller: StackRightController

  @input
  @hint("off | selftest | ghost | mistake | complete")
  @widget(new ComboBoxWidget([
    new ComboBoxItem("off", "off"),
    new ComboBoxItem("selftest", "selftest"),
    new ComboBoxItem("ghost", "ghost"),
    new ComboBoxItem("mistake", "mistake"),
    new ComboBoxItem("complete", "complete"),
  ]))
  mode: string = "off"

  @input
  @hint("Seconds to wait after start before driving")
  startDelaySec: number = 1.5

  private passed = 0
  private failed = 0

  onAwake(): void {
    if (this.mode === "off") return
    this.createEvent("OnStartEvent").bind(() => {
      this.wait(this.startDelaySec).then(() => this.runMode())
    })
  }

  private async runMode(): Promise<void> {
    const c = this.controller
    print("[StackRightTest] mode = " + this.mode)
    if (this.mode === "selftest") {
      await this.selfTest()
    } else if (this.mode === "ghost") {
      for (let i = 0; i < 3; i++) this.dropOnSlot(i)
      c.simulateGrab(3)
      // Hold the carton in the air in front of the pallet, as if carried there.
      const held = c.getSlotWorldPosition(3).add(new vec3(20, 75, 35))
      this.cartonObject(3).getTransform().setWorldPosition(held)
    } else if (this.mode === "mistake") {
      c.tipDurationSec = 120 // demo only: keep the tip up long enough to frame a screenshot
      c.simulateGrab(7)
      c.simulateRelease(7, c.getPalletWorldPosition().add(new vec3(0, 40, 0)))
    } else if (this.mode === "complete") {
      for (let i = 0; i < 8; i++) this.dropOnSlot(i)
    }
  }

  // ---------------------------------------------------------------------------------------
  // Self-test: one block per done criterion in devpost/design-brief.md
  // ---------------------------------------------------------------------------------------
  private async selfTest(): Promise<void> {
    const c = this.controller
    c.reset()
    await this.wait(0.3)

    // DC1: pallet on the floor ~1 m ahead, shelf bay with 8 cartons ~1.4 m to the right.
    const cam = c.getCameraWorldPosition()
    const pallet = c.getPalletWorldPosition()
    const shelf = c.getShelfWorldPosition()
    this.check("DC1", "pallet ~100 cm ahead (got " + (cam.z - pallet.z).toFixed(0) + ")", cam.z - pallet.z >= 80 && cam.z - pallet.z <= 120)
    this.check("DC1", "pallet centred (dx " + (pallet.x - cam.x).toFixed(0) + ")", Math.abs(pallet.x - cam.x) < 20)
    this.check("DC1", "pallet on floor, " + (cam.y - pallet.y).toFixed(0) + " cm below eyes", cam.y - pallet.y >= 140 && cam.y - pallet.y <= 170)
    this.check("DC1", "shelf ~140 cm right (got " + (shelf.x - cam.x).toFixed(0) + ")", shelf.x - cam.x >= 120 && shelf.x - cam.x <= 160)
    this.check("DC1", "8 cartons", c.getCartonCount() === 8)
    let onShelf = true
    for (let i = 0; i < c.getCartonCount(); i++) {
      const p = c.getCartonWorldPosition(i)
      if (c.isCartonPlaced(i) || Math.abs(p.x - shelf.x) > 30 || Math.abs(p.z - shelf.z) > 120 || p.y < shelf.y + 35) onShelf = false
    }
    this.check("DC1", "all 8 cartons sit on the shelf bay", onShelf)
    this.check("DC1", "counter reads 0 / 8", c.getCounterText() === "0 / 8")
    this.check("DC1", "first carton glows on the shelf", c.isCartonGlowing(0))

    // DC2: grabbing the correct next carton shows its ghost with "Layer N · Heavy/Light · kg".
    this.check("DC2", "no ghost before grab", !c.isGhostVisible())
    c.simulateGrab(0)
    this.check("DC2", "ghost visible after grabbing next carton", c.isGhostVisible())
    this.check("DC2", "ghost sits on carton 0's slot", c.getGhostWorldPosition().distance(c.getSlotWorldPosition(0)) < 0.5)
    this.check("DC2", "tag reads '" + c.getGhostTagText() + "'", c.isGhostTagVisible() && c.getGhostTagText() === ghostTagText(PICK_LIST[0]) && c.getGhostTagText() === "Layer 1 · Heavy · 14 kg")

    // DC3: drop within 15 cm snaps, counter goes up, next ghost appears on next grab.
    c.simulateRelease(0, c.getSlotWorldPosition(0).add(new vec3(10, 5, 0)))
    this.check("DC3", "carton 0 snapped (dropped 10 cm off)", c.isCartonPlaced(0))
    this.check("DC3", "snapped square onto the slot", c.getCartonWorldPosition(0).distance(c.getSlotWorldPosition(0)) < 0.5)
    this.check("DC3", "counter reads 1 / 8", c.getCounterText() === "1 / 8")
    this.check("DC3", "ghost hidden after placing", !c.isGhostVisible() && !c.isGhostTagVisible())
    c.simulateGrab(1)
    this.check("DC3", "next ghost appears on grabbing carton 1", c.isGhostVisible() && c.getGhostWorldPosition().distance(c.getSlotWorldPosition(1)) < 0.5)
    this.check("DC3", "next tag reads '" + c.getGhostTagText() + "'", c.getGhostTagText() === ghostTagText(PICK_LIST[1]))
    c.simulateRelease(1, c.getSlotWorldPosition(1).add(new vec3(0, 5, 0)))
    this.check("DC3", "carton 1 snapped, counter 2 / 8", c.isCartonPlaced(1) && c.getCounterText() === "2 / 8")
    const before = c.getMistakes()
    c.simulateGrab(2)
    c.simulateRelease(2, c.getSlotWorldPosition(2).add(new vec3(0, 5, 30)))
    this.check("DC3", "drop 30 cm off the ghost (on pallet) does not snap", !c.isCartonPlaced(2) && c.getMistakes() === before + 1)
    await this.settle()
    c.simulateGrab(2)
    // 90 cm toward the user from the pallet centre: on the floor in front of the pallet.
    c.simulateRelease(2, c.getPalletWorldPosition().add(new vec3(0, 30, 90)))
    this.check("DC3", "release off the pallet: back to shelf, no mistake", !c.isCartonPlaced(2) && c.getMistakes() === before + 1)
    await this.settle()

    // DC4: crushable carton dropped while heavy is due -> back to shelf + red tip.
    const m = c.getMistakes()
    c.simulateGrab(7)
    this.check("DC4", "no ghost for a carton that isn't next", !c.isGhostVisible())
    c.simulateRelease(7, c.getPalletWorldPosition().add(new vec3(0, 40, 0)))
    this.check("DC4", "chips not placed, sliding back", !c.isCartonPlaced(7) && c.isCartonReturning(7))
    this.check("DC4", "red tip shows '" + c.getTipText() + "'", c.isTipVisible() && c.getTipText() === "Chips go on top. Heavy first.")
    this.check("DC4", "counts one mistake", c.getMistakes() === m + 1)
    await this.settle()
    this.check("DC4", "chips back at home on the shelf", c.getCartonWorldPosition(7).distance(c.getCartonHomePosition(7)) < 0.5)
    await this.wait(4.2)
    this.check("DC4", "tip hides after ~4 s", !c.isTipVisible())

    // DC5: after all 8, the completion card shows time + mistakes; Reset clears the pallet.
    for (let i = 2; i < 8; i++) this.dropOnSlot(i)
    this.check("DC5", "all 8 placed, counter 8 / 8", c.isComplete() && c.getCounterText() === "8 / 8")
    const card = c.getCompletionText()
    this.check("DC5", "completion card visible", c.isCompletionVisible())
    this.check("DC5", "card: '" + card.replace(/\n/g, " | ") + "'",
      card.indexOf("Time ") >= 0 && card.indexOf("Mistakes " + c.getMistakes()) >= 0 && card.indexOf("Wrap and label") >= 0)
    await this.wait(1)
    this.check("DC5", "card stays up", c.isCompletionVisible())
    c.pressReset()
    let allHome = true
    for (let i = 0; i < 8; i++) if (c.isCartonPlaced(i) || c.getCartonWorldPosition(i).distance(c.getCartonHomePosition(i)) > 0.5) allHome = false
    this.check("DC5", "Reset: pallet cleared, all cartons home", allHome)
    this.check("DC5", "Reset: counter 0 / 8, card hidden, mistakes 0", c.getCounterText() === "0 / 8" && !c.isCompletionVisible() && c.getMistakes() === 0)

    print("[StackRightTest] DONE: " + this.passed + " passed, " + this.failed + " failed")
  }

  // ---------------------------------------------------------------------------------------
  private dropOnSlot(i: number): void {
    this.controller.simulateGrab(i)
    this.controller.simulateRelease(i, this.controller.getSlotWorldPosition(i).add(new vec3(0, 5, 0)))
  }

  private cartonObject(i: number): SceneObject {
    return this.controller.pickList.getChild(i)
  }

  private check(dc: string, what: string, ok: boolean): void {
    if (ok) this.passed++
    else this.failed++
    print("[StackRightTest] " + (ok ? "PASS" : "FAIL") + " " + dc + ": " + what)
  }

  private async settle(): Promise<void> {
    for (let k = 0; k < 30; k++) {
      let busy = false
      for (let i = 0; i < this.controller.getCartonCount(); i++) if (this.controller.isCartonReturning(i)) busy = true
      if (!busy) return
      await this.wait(0.1)
    }
  }

  private wait(sec: number): Promise<void> {
    return new Promise((resolve) => {
      const ev = this.createEvent("DelayedCallbackEvent")
      ev.bind(() => resolve())
      ev.reset(sec)
    })
  }
}
// StackRightCartonLabelUI.ts
// Owns: the printed labels on one carton (name + "14 kg · HEAVY" / "FRAGILE") on the faces the
// user sees: the side facing the pallet (-X, seen while the carton is on the shelf), the near
// side (+Z, seen on the pallet) and the top. Created at runtime by the controller on each carton.
// Must not: hold game state.

@component
export class StackRightCartonLabelUI extends BaseScriptComponent {
  @ui.label('<span style="color: #60A5FA;">StackRightCartonLabelUI – printed carton labels</span>')
  @ui.separator

  @ui.label('<span style="color: #60A5FA;">Settings</span>')
  @ui.group_start("Settings")
  @input
  @hint("Label text size (about 44 = 1 cm em height)")
  @widget(new SliderWidget(40, 300, 1))
  labelSize: number = 120

  @ui.group_end

  setup(name: string, detail: string, size: vec3): void {
    const hx = size.x / 2, hy = size.y / 2, hz = size.z / 2
    const off = 0.3
    // -X face (seen from the pallet side while on the shelf): +Z normal rotated to -X
    this.face("LabelSide", name, detail, new vec3(-hx - off, 0, 0), quat.angleAxis(-Math.PI / 2, vec3.up()), size.z, size.y)
    // +Z face (near side on the pallet)
    this.face("LabelFront", name, detail, new vec3(0, 0, hz + off), quat.quatIdentity(), size.x, size.y)
    // top face, readable from the user's side
    this.face("LabelTop", name, detail, new vec3(0, hy + off, 0), quat.angleAxis(-Math.PI / 2, vec3.right()), size.x, size.z)
  }

  private face(objName: string, name: string, detail: string, pos: vec3, rot: quat, w: number, h: number): void {
    const so = global.scene.createSceneObject(objName)
    so.setParent(this.sceneObject)
    so.getTransform().setLocalPosition(pos)
    so.getTransform().setLocalRotation(rot)
    const t = so.createComponent("Component.Text") as Text
    t.text = name + "\n" + detail
    t.size = this.labelSize
    t.depthTest = true
    t.textFill.color = new vec4(1, 1, 1, 1)
    t.horizontalAlignment = HorizontalAlignment.Center
    t.verticalAlignment = VerticalAlignment.Center
    t.horizontalOverflow = HorizontalOverflow.Shrink
    t.verticalOverflow = VerticalOverflow.Shrink
    const hw = w / 2 - 2
    const hh = h / 2 - 2
    t.layoutRect = Rect.create(-hw, hw, -hh, hh)
  }
}
// StackRightLabelUI.ts
// Owns: one world-space label = UIKit BackPlate (translucent panel) + one light Text.
// Used for the ghost tag, the "3 / 8" counter, the red tip, and the completion card.
// Passive view: the controller pushes text/visibility in through setText / setVisible.
// Expects: nothing wired; all fields are Inspector-tunable presentation.
// Must not: hold game state or make game decisions.
import {BackPlate} from "SpectaclesUIKit.lspkg/Scripts/BackPlate"
import WorldCameraFinderProvider from "SpectaclesInteractionKit.lspkg/Providers/CameraProvider/WorldCameraFinderProvider"

@component
export class StackRightLabelUI extends BaseScriptComponent {
  @ui.label('<span style="color: #60A5FA;">StackRightLabelUI – translucent panel with light text</span>')
  @ui.separator

  @ui.label('<span style="color: #60A5FA;">Settings</span>')
  @ui.group_start("Settings")
  @input
  @hint("Panel width in cm")
  @widget(new SliderWidget(4, 120, 0.5))
  panelWidth: number = 30

  @input
  @hint("Panel height in cm")
  @widget(new SliderWidget(2, 60, 0.5))
  panelHeight: number = 8

  @input
  @hint("Text size (about 44 = 1 cm em height; 180 = about 4 cm)")
  @widget(new SliderWidget(40, 400, 1))
  textSize: number = 180

  @input("vec4", "{1,1,1,1}")
  @hint("Text colour. Keep it light: the Specs display is additive, so dark colours look see-through.")
  @widget(new ColorWidget())
  textColor: vec4 = new vec4(1, 1, 1, 1)

  @input
  @hint("Text shown before the controller sets anything")
  initialText: string = ""

  @input
  @hint("Visible when the Lens starts")
  startVisible: boolean = true

  @input
  @hint("Turn the panel every frame so it faces the user's eyes")
  faceCamera: boolean = true
  @ui.group_end

  private text: Text
  private backPlate: BackPlate
  private ready = false
  private wantVisible = true
  private currentText = ""
  private camT: Transform | null = null

  onAwake(): void {
    this.wantVisible = this.startVisible
    this.currentText = this.initialText
    this.sceneObject.createComponent("Component.Canvas")
    this.backPlate = this.sceneObject.createComponent(BackPlate.getTypeName()) as BackPlate
    this.backPlate.size = new vec2(this.panelWidth, this.panelHeight)

    const content = global.scene.createSceneObject("Content")
    content.setParent(this.sceneObject)
    content.getTransform().setLocalPosition(new vec3(0, 0, 0.6))
    this.text = content.createComponent("Component.Text") as Text
    this.text.depthTest = true
    this.text.size = this.textSize
    this.text.textFill.color = this.textColor
    this.text.horizontalAlignment = HorizontalAlignment.Center
    this.text.verticalAlignment = VerticalAlignment.Center
    this.text.horizontalOverflow = HorizontalOverflow.Shrink
    this.text.verticalOverflow = VerticalOverflow.Shrink
    const hw = this.panelWidth / 2 - 0.8
    const hh = this.panelHeight / 2 - 0.5
    this.text.layoutRect = Rect.create(-hw, hw, -hh, hh)
    this.text.text = this.currentText

    this.backPlate.onInitialized.add(() => {
      this.backPlate.size = new vec2(this.panelWidth, this.panelHeight)
      this.ready = true
      this.sceneObject.enabled = this.wantVisible
    })

    this.createEvent("UpdateEvent").bind(() => this.faceUser())
  }

  setText(msg: string): void {
    this.currentText = msg
    if (this.text) this.text.text = msg
  }

  getText(): string {
    return this.currentText
  }

  setTextColor(c: vec4): void {
    if (this.text) this.text.textFill.color = c
  }

  setVisible(v: boolean): void {
    this.wantVisible = v
    if (this.ready) this.sceneObject.enabled = v
  }

  /** Logical visibility (what the controller asked for). */
  isVisible(): boolean {
    return this.wantVisible
  }

  private faceUser(): void {
    if (!this.faceCamera) return
    if (!this.camT) {
      const cam = WorldCameraFinderProvider.getInstance()
      if (!cam) return
      this.camT = cam.getTransform()
    }
    const t = this.sceneObject.getTransform()
    const dir = this.camT.getWorldPosition().sub(t.getWorldPosition())
    if (dir.length < 0.001) return
    t.setWorldRotation(quat.lookAt(dir.normalize(), vec3.up()))
  }
}
# Stack Right LEAF scenarios (written, NOT yet run)

These are kept outside `Assets/` because the LEAF package (`Leaf.lspkg`) is not installed yet.
Inside `Assets/` they would break the TypeScript build.

To use them:
1. Restart Lens Studio, then rebuild the scene from `../stackright-scene-bootstrap.json`
   (VirtualScene apply `phaseA` → recompile → apply `phaseB` → save).
2. Sign in to Lens Studio and install LEAF (Asset Library, or the `specs-leaf-install-packages` skill).
3. Copy every `.ts` file here into `Assets/Tests/` (imports expect `../Scripts/StackRightController`).
4. Add a root SceneObject `LeafIndex` with the `LeafIndex.ts` script, recompile, and run the scenarios.

| Scenario id | Done criterion |
|---|---|
| dc1-layout | 1. Pallet ~1 m ahead on the floor; shelf ~1.4 m right with 8 cartons |
| dc2-ghost-on-grab | 2. Correct grab shows the ghost and the "Layer N · Heavy/Light · kg" tag |
| dc3-snap-counter-next | 3. Drop within 15 cm snaps, the counter goes up, next ghost appears |
| dc4-wrong-carton-tip | 4. Crushable when heavy is due: back to the shelf + red tip |
| dc5-complete-and-reset | 5. Completion card with time + mistakes; Reset (real button pinch) clears |
| reset-reach-ik | Extra: IK reachability of the Reset button |

Note: DC2–DC5 drive grab/release through the controller's `simulateGrab`/`simulateRelease` hooks
(same code path as SIK `onManipulationStart/End`), not through a simulated mouse drag. A real
SIK carry of a carton from shelf to pallet is not covered by a test; check it by hand in
Interactive Preview.
// Shared helpers for the Stack Right LEAF scenarios. Lives in Assets/Tests/.
import {findSceneObjectByName, sleep} from "Leaf.lspkg/Utils/common/Utils"
import {StackRightController} from "../Scripts/StackRightController"

export function getController(): StackRightController {
  const so = findSceneObjectByName("StackRightController")
  if (!so) throw new Error("StackRightController scene object not found")
  const c = so.getComponent(StackRightController.getTypeName()) as StackRightController
  if (!c) throw new Error("StackRightController component not found")
  return c
}

/** Drops carton i a few cm above its slot (inside the 15 cm snap radius). */
export function dropOnSlot(c: StackRightController, i: number): void {
  c.simulateGrab(i)
  c.simulateRelease(i, c.getSlotWorldPosition(i).add(new vec3(0, 5, 0)))
}

/** Waits until every returning carton has slid back to the shelf. */
export async function settle(c: StackRightController): Promise<void> {
  for (let k = 0; k < 40; k++) {
    let busy = false
    for (let i = 0; i < c.getCartonCount(); i++) if (c.isCartonReturning(i)) busy = true
    if (!busy) return
    await sleep(100)
  }
}

export async function freshPallet(c: StackRightController): Promise<void> {
  c.reset()
  await sleep(300)
}

/** The Reset button's UIKit Button lives on a runtime child "ButtonFace" under "ResetButton". */
export function resetButtonFaceName(): string {
  return "ButtonFace"
}
// DC4: dropping a crushable carton when a heavy one is due sends it back to the shelf and
// shows the red tip (for about 4 s).
import {Scenario} from "Leaf.lspkg/Scenarios/scenario/Scenario"
import {expect} from "Leaf.lspkg/Utils/common/Expect"
import {sleep} from "Leaf.lspkg/Utils/common/Utils"
import {getController, freshPallet, settle} from "./StackRightLeafHelpers"

@component
export class StackRightDC4WrongCartonScenario extends Scenario {
  async run(): Promise<void> {
    await sleep(1500)
    const c = getController()
    await freshPallet(c)

    const CHIPS = 7
    const m = c.getMistakes()
    c.simulateGrab(CHIPS)
    await sleep(100)
    expect(c.isGhostVisible()).toBe(false)
    c.simulateRelease(CHIPS, c.getPalletWorldPosition().add(new vec3(0, 60, 0)))
    await sleep(200)

    expect(c.isCartonPlaced(CHIPS)).toBe(false)
    expect(c.getMistakes()).toBe(m + 1)
    expect(c.isTipVisible()).toBe(true)
    expect(c.getTipText()).toBe("Chips go on top. Heavy first.")
    expect(c.isCartonReturning(CHIPS)).toBe(true)
    await settle(c)
    expect(c.getCartonWorldPosition(CHIPS).distance(c.getCartonHomePosition(CHIPS)) < 1).toBe(true)
    expect(c.getPlacedCount()).toBe(0)

    // Wrong heavy carton: "Not this one yet" tip.
    c.simulateGrab(4)
    c.simulateRelease(4, c.getPalletWorldPosition().add(new vec3(0, 60, 0)))
    await sleep(200)
    expect(c.getMistakes()).toBe(m + 2)
    expect(c.getTipText()).toBe("Not this one yet. Follow the arrow.")
    await settle(c)

    // Tip hides after about 4 s.
    await sleep(4500)
    expect(c.isTipVisible()).toBe(false)
  }
}
